import { useEffect, useState } from 'react'
import { CancelUpload, UploadFile } from '../../../wailsjs/go/main/App'
import { handlePromiseRejection } from '../../lib/globalErrorHandler'

export type UploadStatus =
  /** Enqueued, waiting for the worker to reach it. */
  | 'queued'
  /** Was queued, then reverted here by cancelRemaining/cancelAll before the
   * worker reached it — never actually attempted. resumePaused re-queues
   * these in bulk. */
  | 'paused'
  /** The worker is currently awaiting UploadFile for it. */
  | 'uploading'
  /** Terminal: UploadFile resolved. */
  | 'done'
  /** Terminal: UploadFile rejected; .error holds the message. Retry re-queues it. */
  | 'error'
  /** Terminal: aborted mid-upload via cancel/cancelAll. Retry re-queues it. */
  | 'cancelled'

export interface UploadJob {
  path: string
  folderId: string
  name: string
}

export interface UploadEntry extends UploadJob {
  status: UploadStatus
  error?: string
}

// Per-file upload status, driven by a sequential (concurrency = 1) worker.
// A module-level singleton (like ../../lib/pageCache) rather than a hook:
// there is only ever one upload run in flight for the app, so the queue's
// lifetime doesn't need to be tied to any one component instance. Callers
// resolve each file's destination folder/name up front and pass in an
// ordered list of jobs — this module only knows how to run them one at a
// time and track status, not about the file tree or Drive assignments.
const filesByPath = new Map<string, UploadEntry>()
let pendingPaths: string[] = []
const listeners = new Set<() => void>()
let running = false
let cancelled = false

// Paths whose in-flight upload was cancelled. runQueue checks this once the
// awaited UploadFile call settles (success or failure) and, if present,
// leaves the status as 'cancelled' instead of overwriting it with
// 'done'/'error' — the request may have raced ahead of the abort signal, but
// the user's intent to cancel wins either way.
const cancelledInFlight = new Set<string>()

function notify() {
  for (const fn of listeners) fn()
}

export function subscribe(fn: () => void): () => void {
  listeners.add(fn)
  return () => listeners.delete(fn)
}

export function useUploadQueueRender() {
  const [, setTick] = useState(0)
  useEffect(() => subscribe(() => setTick(t => t + 1)), [])
}

export function getStatus(path: string): UploadEntry | undefined {
  return filesByPath.get(path)
}

// True once none of the given files are still queued or uploading — i.e.
// each has either reached a terminal state (done/error) or was never
// started. Callers use this to know when it's safe to let the upload
// modal close.
export function hasSettled(paths: string[]): boolean {
  return !paths.some(path => {
    const status = filesByPath.get(path)?.status
    return status === 'queued' || status === 'uploading'
  })
}

// True if any of the given files are paused — i.e. there's a cancelled batch
// the modal can offer to resume.
export function hasPaused(paths: string[]): boolean {
  return paths.some(path => filesByPath.get(path)?.status === 'paused')
}

function updateStatus(path: string, status: UploadStatus, error?: string) {
  const existing = filesByPath.get(path)!
  filesByPath.set(path, { ...existing, status, error })
  notify()
}

async function runQueue() {
  if (running) return
  running = true
  while (!cancelled && pendingPaths.length > 0) {
    const path = pendingPaths.shift()!
    const job = filesByPath.get(path)!
    updateStatus(path, 'uploading')
    try {
      await UploadFile(job.path, job.folderId, job.name)
      if (!cancelledInFlight.delete(path)) updateStatus(path, 'done')
    } catch (e) {
      if (!cancelledInFlight.delete(path)) updateStatus(path, 'error', String(e))
    }
  }
  running = false
}

function enqueue(newJobs: UploadJob[]) {
  if (newJobs.length === 0) return
  cancelled = false
  for (const job of newJobs) {
    filesByPath.set(job.path, { ...job, status: 'queued', error: undefined })
    pendingPaths.push(job.path)
  }
  notify()
  void runQueue()
}

export function start(newJobs: UploadJob[]): void {
  enqueue(newJobs)
}

export function retry(job: UploadJob): void {
  enqueue([job])
}

// Stops starting new files; does not abort an in-flight request. Files
// still waiting their turn are marked paused since they were never attempted.
export function cancelRemaining(): void {
  cancelled = true
  for (const path of pendingPaths) updateStatus(path, 'paused')
  pendingPaths = []
}

// Aborts the file currently uploading. A no-op for any other status —
// queued files are handled by cancelRemaining, and done/error/cancelled are
// already settled. Marks the file 'cancelled' immediately rather than
// waiting on the CancelUpload round-trip or on however UploadFile's promise
// ends up settling.
export function cancel(path: string): void {
  if (filesByPath.get(path)?.status !== 'uploading') return
  cancelledInFlight.add(path)
  updateStatus(path, 'cancelled')
  CancelUpload(path).catch(handlePromiseRejection('Canceling upload failed'))
}

// The modal's single Cancel button: aborts whatever is currently uploading
// and pauses everything still queued. Concurrency is 1, so at most one entry
// can be 'uploading' at a time.
export function cancelAll(): void {
  cancelRemaining()
  for (const path of filesByPath.keys()) cancel(path)
}

// Re-queues every paused file among the given paths — i.e. resumes a batch
// left over from cancelAll. The file that was actually mid-upload when
// cancelled is left alone; it's 'cancelled', not 'paused', and already has
// its own per-row Retry button.
export function resumePaused(paths: string[]): void {
  const jobs = paths
    .map(path => filesByPath.get(path))
    .filter((entry): entry is UploadEntry => entry?.status === 'paused')
  enqueue(jobs)
}

export function reset(): void {
  if (!hasSettled(Array.from(filesByPath.keys()))) {
    // Callers must only invoke this once hasSettled() is true for all files;
    // otherwise a request from the discarded run could still be in flight and
    // would resurface after this call.
    throw new Error('reset() called while an upload is still in flight')
  }
  cancelled = false
  running = false
  cancelledInFlight.clear()
  filesByPath.clear()
  pendingPaths = []
  notify()
}

import { ActionIcon, Box, Button, Group, Loader, Modal, Stack, Text } from '@mantine/core'
import { IconExternalLink } from '@tabler/icons-react'
import TruncatedText from '../TruncatedText'
import { LocalFile, LocalFileGroup, flattenFiles } from './useFileTree'
import * as uploadQueue from './uploadQueue'
import { OpenDriveFolder } from '../../../wailsjs/go/main/App'
import { handlePromiseRejection } from '../../lib/globalErrorHandler'
import styles from './UploadModal.module.css'

interface Props {
  opened: boolean
  tree: LocalFileGroup
  onClose: () => void
}

// Per-file status lives in the uploadQueue module singleton, not in this
// component's state — it re-renders by subscribing, the same pattern
// lib/pageCache's consumers use.
export default function UploadModal({ opened, tree, onClose }: Props) {
  uploadQueue.useUploadQueueRender()

  const paths = flattenFiles(tree).map(f => f.path)
  const settled = uploadQueue.hasSettled(paths)
  const canResume = settled && uploadQueue.hasPaused(paths)

  return (
    <Modal
      opened={opened}
      onClose={onClose}
      title="Uploading to Drive"
      closeOnClickOutside={false}
      closeOnEscape={false}
      withCloseButton={false}
      size="md"
    >
      <Stack gap="md">
        <Stack gap={10}>
          {tree.files.map(file => <FileRow key={file.path} file={file} />)}
          {tree.subgroups.map(group => (
            <GroupSection key={group.name} group={group} groupKey={group.name} />
          ))}
        </Stack>
        <Group justify="flex-end">
          <Button
            variant="default"
            disabled={settled && !canResume}
            onClick={() => (canResume ? uploadQueue.resumePaused(paths) : uploadQueue.cancelAll())}
          >
            {canResume ? 'Resume' : 'Cancel'}
          </Button>
          <Button disabled={!settled} onClick={onClose}>
            Close
          </Button>
        </Group>
      </Stack>
    </Modal>
  )
}

function GroupSection({ group, groupKey }: { group: LocalFileGroup; groupKey: string }) {
  const groupFiles = flattenFiles(group)
  const doneCount = groupFiles.filter(f => uploadQueue.getStatus(f.path)?.status === 'done').length

  return (
    <Box pl={12}>
      <Group justify="space-between" gap={8} mb={4} wrap="nowrap">
        <TruncatedText label={group.name} size="sm" fw={600}>📁 {group.name}</TruncatedText>
        <Text size="xs" c="dimmed" className={styles.groupCount}>{doneCount}/{groupFiles.length}</Text>
      </Group>
      <Stack gap={10}>
        {group.files.map(file => <FileRow key={file.path} file={file} />)}
        {group.subgroups.map(sub => (
          <GroupSection key={sub.name} group={sub} groupKey={`${groupKey}/${sub.name}`} />
        ))}
      </Stack>
    </Box>
  )
}

function FileRow({ file }: { file: LocalFile }) {
  const entry = uploadQueue.getStatus(file.path)
  const status = entry?.status

  return (
    <Group justify="space-between" wrap="nowrap" gap={8}>
      <TruncatedText label={file.name} size="sm" className={styles.fileName}>{file.name}</TruncatedText>
      {status === 'queued' && <Text size="sm" c="dimmed">Queued</Text>}
      {status === 'uploading' && (
        <Group gap={6} wrap="nowrap">
          <Loader size="xs" />
          <Text size="sm" c="dimmed">Uploading…</Text>
        </Group>
      )}
      {status === 'done' && <Text size="sm" c="green">✓ Uploaded</Text>}
      {(status === undefined || status === 'paused') && <Text size="sm" c="dimmed">Not uploaded</Text>}
      {status === 'cancelled' && (
        <Group gap={8} wrap="nowrap">
          <Text size="sm" c="dimmed">Cancelled</Text>
          <Button size="xs" variant="default" onClick={() => uploadQueue.retry(entry!)}>
            Retry
          </Button>
        </Group>
      )}
      {status === 'error' && (
        <Group gap={8} wrap="nowrap">
          <TruncatedText label={entry?.error ?? ''} size="sm" c="red" className={styles.errorText}>
            ⚠ {entry?.error}
          </TruncatedText>
          <Button size="xs" variant="default" onClick={() => uploadQueue.retry(entry!)}>
            Retry
          </Button>
        </Group>
      )}
      {entry && (
        <ActionIcon
          variant="subtle"
          size="sm"
          aria-label={`Open destination Drive folder for ${file.name}`}
          onClick={() => OpenDriveFolder(entry.folderId).catch(handlePromiseRejection('Opening Drive folder failed'))}
        >
          <IconExternalLink size={14} />
        </ActionIcon>
      )}
    </Group>
  )
}

